{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello Chandra जी आपको rechargeable torch की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आप जो seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "rate पता चल जाता है तो।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "मैं समझ सकती हूं पर एक approximate number बता दीजिए ताकि मैं आपको सही seller से connect कर सकूं कितने piece चाहिए।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "दस से बीस माने दो चार quality में चाहिए दो चार piece आता है ना उस तरह से बीस पच्चीस piece चाहिए सब मिलके"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "चलिए अब power के बारे में बात कर लेते हैं।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए 100 watts या कुछ और?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "तो बोला तो like तो बोला जो चाहिए ना वो कुछ चाहिए था।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "क्षमा कीजिए मैं समझ नहीं पाई।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "क्या आप बता सकते हैं कि आपको power में क्या prefer करेंगे जैसे 1?"
    }
  ]
}
